old = '''\tif t.cfg.PaperTrade {\n\t\t// GTC limit orders fill exactly rawShares at the actual market price (fillPrice),\n\t\t// not the limit ceiling.  The limit only prevents paying more than limitPrice.\n\t\tpaperCost := marketBuyOrderNotional(rawShares, fillPrice)\n\t\tif paperCost > t.paperBalance {\n\t\t\treturn pairArbBuyOutcomeHardError, "", 0, 0, 0, 0, fmt.Errorf("pair arb: insufficient paper balance ($%.2f) for trade ($%.2f)", t.paperBalance, paperCost)\n\t\t}\n\t\tfeeShares = polymarket.ComputeBuyFeeShares(rawShares, fillPrice, t.feeRateBps)\n\t\tactualShares = math.Floor((rawShares-feeShares)*100) / 100\n\t\tt.paperBalance -= paperCost\n\t\tif t.metrics != nil {\n\t\t\tentryToPositionMs := time.Since(entryStart).Milliseconds()\n\t\t\tt.metrics.Record("order_place", entryToPositionMs)\n\t\t\tt.metrics.Record("entry_preflight", preflightMS)\n\t\t\tt.metrics.Record("entry_to_position", entryToPositionMs)\n\t\t}\n\t\treturn pairArbBuyOutcomeFilled, fmt.Sprintf("PAPER-%s-%d", strings.ToUpper(requestName), time.Now().UnixMilli()), fillPrice, actualShares, feeShares, paperCost, nil\n\t}\n'''
new = '''\tif t.cfg.PaperTrade {\n\t\t// REALPAPER v1: validate the simulated buy against the current real\n\t\t// Polymarket CLOB ask book. The purchased bot's original PAPER branch\n\t\t// assumes every requested share fills at signalPrice; this branch instead\n\t\t// requires enough displayed ask depth at or below limitPrice and charges\n\t\t// the actual displayed-depth VWAP. No live order is submitted.\n\t\tif t.orders == nil {\n\t\t\treturn pairArbBuyOutcomeHardError, "", 0, 0, 0, 0, fmt.Errorf("realpaper: nil orders client")\n\t\t}\n\t\tbookCtx, cancelBook := context.WithTimeout(ctx, 1500*time.Millisecond)\n\t\tbook, bookErr := t.orders.GetOrderBook(bookCtx, tokenID)\n\t\tcancelBook()\n\t\tif bookErr != nil {\n\t\t\treturn pairArbBuyOutcomeHardError, "", 0, 0, 0, 0, fmt.Errorf("realpaper: get orderbook: %w", bookErr)\n\t\t}\n\t\tif book == nil || len(book.Asks) == 0 {\n\t\t\tt.logger.Info("realpaper: not filled; empty ask book", zap.String("request", requestName), zap.String("token_id", tokenID))\n\t\t\treturn pairArbBuyOutcomeNotFilled, "", 0, 0, 0, 0, nil\n\t\t}\n\n\t\t// Parse eligible asks and insertion-sort by price ascending. Avoids adding\n\t\t// another package import to the purchased source file.\n\t\ttype rpLevel struct { price, size float64 }\n\t\tlevels := make([]rpLevel, 0, len(book.Asks))\n\t\tfor _, a := range book.Asks {\n\t\t\tpv, perr := strconv.ParseFloat(strings.TrimSpace(a.Price), 64)\n\t\t\tsv, serr := strconv.ParseFloat(strings.TrimSpace(a.Size), 64)\n\t\t\tif perr != nil || serr != nil || pv <= 0 || sv <= 0 || pv > limitPrice+1e-9 {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tlevels = append(levels, rpLevel{price: pv, size: sv})\n\t\t}\n\t\tfor i := 1; i < len(levels); i++ {\n\t\t\tx := levels[i]\n\t\t\tj := i - 1\n\t\t\tfor ; j >= 0 && levels[j].price > x.price; j-- {\n\t\t\t\tlevels[j+1] = levels[j]\n\t\t\t}\n\t\t\tlevels[j+1] = x\n\t\t}\n\n\t\tremaining := rawShares\n\t\tgrossCost := 0.0\n\t\tfor _, lv := range levels {\n\t\t\tif remaining <= 1e-9 { break }\n\t\t\ttake := lv.size\n\t\t\tif take > remaining { take = remaining }\n\t\t\tgrossCost += take * lv.price\n\t\t\tremaining -= take\n\t\t}\n\t\tif remaining > 1e-6 {\n\t\t\tavailable := rawShares - remaining\n\t\t\tt.logger.Info("realpaper: not filled; insufficient displayed ask depth",\n\t\t\t\tzap.String("request", requestName), zap.String("token_id", tokenID),\n\t\t\t\tzap.Float64("limit_price", limitPrice), zap.Float64("requested_shares", rawShares),\n\t\t\t\tzap.Float64("available_shares", available), zap.Int("eligible_levels", len(levels)))\n\t\t\treturn pairArbBuyOutcomeNotFilled, "", 0, 0, 0, 0, nil\n\t\t}\n\n\t\tfillPrice = grossCost / rawShares\n\t\tfillPrice = math.Round(fillPrice*10000) / 10000\n\t\tpaperCost := marketBuyOrderNotional(rawShares, fillPrice)\n\t\tif paperCost > t.paperBalance {\n\t\t\treturn pairArbBuyOutcomeHardError, "", 0, 0, 0, 0, fmt.Errorf("realpaper: insufficient paper balance ($%.2f) for trade ($%.2f)", t.paperBalance, paperCost)\n\t\t}\n\t\tfeeShares = polymarket.ComputeBuyFeeShares(rawShares, fillPrice, t.feeRateBps)\n\t\tactualShares = math.Floor((rawShares-feeShares)*100) / 100\n\t\tif actualShares <= 0 {\n\t\t\treturn pairArbBuyOutcomeHardError, "", 0, 0, 0, 0, fmt.Errorf("realpaper: fee eats all shares")\n\t\t}\n\t\tt.paperBalance -= paperCost\n\t\tif t.metrics != nil {\n\t\t\tentryToPositionMs := time.Since(entryStart).Milliseconds()\n\t\t\tt.metrics.Record("order_place", entryToPositionMs)\n\t\t\tt.metrics.Record("entry_preflight", preflightMS)\n\t\t\tt.metrics.Record("entry_to_position", entryToPositionMs)\n\t\t}\n\t\tt.logger.Info("realpaper: filled from displayed Polymarket ask depth",\n\t\t\tzap.String("request", requestName), zap.String("token_id", tokenID),\n\t\t\tzap.Float64("signal_price", signalPrice), zap.Float64("limit_price", limitPrice),\n\t\t\tzap.Float64("vwap", fillPrice), zap.Float64("raw_shares", rawShares),\n\t\t\tzap.Float64("actual_shares", actualShares), zap.Float64("paper_cost", paperCost),\n\t\t\tzap.Int("eligible_levels", len(levels)))\n\t\treturn pairArbBuyOutcomeFilled, fmt.Sprintf("REALPAPER-%s-%d", strings.ToUpper(requestName), time.Now().UnixMilli()), fillPrice, actualShares, feeShares, paperCost, nil\n\t}\n'''
if old not in text:
    if 'REALPAPER v1' in text:
        print('RealPaper v1 already applied')
        sys.exit(0)
    print('ERROR: expected original PAPER block not found; refusing to patch')
    sys.exit(2)
backup = p.with_name('trader.go.original-paid')
if not backup.exists():
    backup.write_text(text)
p.write_text(text.replace(old, new, 1))
